```js
'use strict';

const test = require('node:test');
const assert = require('node:assert');
const crypto = require('crypto');
const fs = require('fs');
const os = require('os');
const path = require('path');

const { Verifier, signEnvelope } = require('./verifier');

// ---------------------------------------------------------------------------
// helpers
// ---------------------------------------------------------------------------

const T0 = 1_700_000_000_000;

function tmpDir() {
  return fs.mkdtempSync(path.join(os.tmpdir(), 'rkrw-'));
}

function makeKey(keyId, opts = {}) {
  const { publicKey, privateKey } = crypto.generateKeyPairSync('ed25519');
  return {
    descriptor: {
      keyId,
      publicKey: publicKey.export({ type: 'spki', format: 'pem' }),
      validFrom: opts.validFrom ?? T0 - 3_600_000,
      validUntil: opts.validUntil ?? T0 + 3_600_000,
      region: opts.region ?? 'r1',
    },
    privateKey,
  };
}

let nonceCounter = 0;
function envelope(keyId, issuedAt, payload = { n: 1 }, nonce) {
  return {
    keyId,
    nonce: nonce ?? `nonce-${String(nonceCounter++).padStart(16, '0')}`,
    issuedAt,
    payload,
  };
}

function newVerifier(dir, clock, extra = {}) {
  return new Verifier({
    statePath: path.join(dir, 'state.bin'),
    secret: Buffer.from('test-secret-0123456789abcdef'),
    windowMs: 300_000,
    maxSkewMs: 30_000,
    clock: () => clock.t,
    ...extra,
  });
}

// ---------------------------------------------------------------------------
// tests
// ---------------------------------------------------------------------------

test('accepts a correctly signed fresh message', () => {
  const dir = tmpDir();
  const clock = { t: T0 };
  const { descriptor, privateKey } = makeKey('k1');
  const v = newVerifier(dir, clock).load().addKey(descriptor);

  const env = signEnvelope(envelope('k1', T0), privateKey);
  assert.deepStrictEqual(v.verify(env), {
    ok: true,
    keyId: 'k1',
    fingerprint: require('./verifier').fingerprint(env).toString('hex'),
    issuedAt: T0,
  });
});

test('rejects a replayed message (per-key sliding window)', () => {
  const dir = tmpDir();
  const clock = { t: T0 };
  const { descriptor, privateKey } = makeKey('k1');
  const v = newVerifier(dir, clock).load().addKey(descriptor);
  const env = signEnvelope(envelope('k1', T0), privateKey);

  assert.strictEqual(v.verify(env).ok, true);
  assert.deepStrictEqual(v.verify(env), { ok: false, reason: 'replay' });
  assert.strictEqual(v.windowSize('k1'), 1);
});

test('replay is scoped per key (same nonce on another key is fine)', () => {
  const dir = tmpDir();
  const clock = { t: T0 };
  const a = makeKey('a');
  const b = makeKey('b');
  const v = newVerifier(dir, clock).load().addKey(a.descriptor).addKey(b.descriptor);
  const nonce = 'shared-nonce-0001';
  assert.strictEqual(v.verify(signEnvelope(envelope('a', T0, {}, nonce), a.privateKey)).ok, true);
  assert.strictEqual(v.verify(signEnvelope(envelope('b', T0, {}, nonce), b.privateKey)).ok, true);
});

test('rejects stale and far-future messages (bounded clock skew)', () => {
  const dir = tmpDir();
  const clock = { t: T0 };
  const { descriptor, privateKey } = makeKey('k1');
  const v = newVerifier(dir, clock).load().addKey(descriptor);

  const stale = signEnvelope(envelope('k1', T0 - 300_001), privateKey);
  assert.deepStrictEqual(v.verify(stale), { ok: false, reason: 'stale' });

  const future = signEnvelope(envelope('k1', T0 + 30_001), privateKey);
  assert.deepStrictEqual(v.verify(future), { ok: false, reason: 'clock_skew_future' });

  // just inside the skew allowance is accepted
  const skewed = signEnvelope(envelope('k1', T0 + 29_000), privateKey);
  assert.strictEqual(v.verify(skewed).ok, true);
});

test('rejects unknown keys and bad signatures without poisoning state', () => {
  const dir = tmpDir();
  const clock = { t: T0 };
  const { descriptor, privateKey } = makeKey('k1');
  const other = makeKey('other');
  const v = newVerifier(dir, clock).load().addKey(descriptor);

  assert.deepStrictEqual(v.verify(signEnvelope(envelope('nope', T0), privateKey)), {
    ok: false,
    reason: 'unknown_key',
  });

  // forged signature must not create a replay entry
  const forged = signEnvelope(envelope('k1', T0), other.privateKey);
  assert.deepStrictEqual(v.verify(forged), { ok: false, reason: 'bad_signature' });
  assert.strictEqual(v.windowSize('k1'), 0);
});

test('honours key validity intervals and overlapping rotation windows', () => {
  const dir = tmpDir();
  const clock = { t: T0 };
  const oldK = makeKey('old', { validFrom: T0 - 100_000, validUntil: T0 + 100_000 });
  const newK = makeKey('new', { validFrom: T0 - 50_000, validUntil: T0 + 200_000 });
  const v = newVerifier(dir, clock).load().addKey(oldK.descriptor).addKey(newK.descriptor);

  // overlap region: both keys accepted
  assert.strictEqual(v.verify(signEnvelope(envelope('old', T0), oldK.privateKey)).ok, true);
  assert.strictEqual(v.verify(signEnvelope(envelope('new', T0), newK.privateKey)).ok, true);

  // new key not valid before its validFrom
  const early = signEnvelope(envelope('new', T0 - 60_000), newK.privateKey);
  assert.deepStrictEqual(v.verify(early), { ok: false, reason: 'key_not_yet_valid' });

  // old key expired
  const late = signEnvelope(envelope('old', T0 + 150_000), oldK.privateKey);
  assert.deepStrictEqual(v.verify(late), { ok: false, reason: 'key_expired' });
});

test('delayed revocation: pre-revocation messages stay valid, later ones rejected', () => {
  const dir = tmpDir();
  const clock = { t: T0 };
  const { descriptor, privateKey } = makeKey('k1');
  const v = newVerifier(dir, clock).load().addKey(descriptor);

  // We learn about a revocation effective at T0, but notices can arrive late.
  const pre = signEnvelope(envelope('k1', T0 - 1_000), privateKey);
  assert.strictEqual(v.verify(pre).ok, true);

  v.revoke('k1', T0);

  const post = signEnvelope(envelope('k1', T0 + 1_000), privateKey);
  assert.deepStrictEqual(v.verify(post), { ok: false, reason: 'revoked_key' });

  // A message issued before the effective revocation time is still valid.
  const pre2 = signEnvelope(envelope('k1', T0 - 500), privateKey);
  assert.strictEqual(v.verify(pre2).ok, true);
});

test('revocation notices merge out of order (keep earliest effective time)', () => {
  const dir = tmpDir();
  const clock = { t: T0 };
  const { descriptor, privateKey } = makeKey('k1');
  const v = newVerifier(dir, clock).load().addKey(descriptor);

  v.revoke('k1', T0 - 10_000);
  v.revoke('k1', T0 + 10_000); // late/conflicting notice must not move it later
  assert.strictEqual(v.registry.get('k1').revokedAt, T0 - 10_000);

  const between = signEnvelope(envelope('k1', T0), privateKey);
  assert.deepStrictEqual(v.verify(between), { ok: false, reason: 'revoked_key' });
});

test('state survives restart: replay window and revocations persist', () => {
  const dir = tmpDir();
  const clock = { t: T0 };
  const { descriptor, privateKey } = makeKey('k1');

  const v1 = newVerifier(dir, clock).load().addKey(descriptor);
  const env = signEnvelope(envelope('k1', T0), privateKey);
  assert.strictEqual(v1.verify(env).ok, true);
  v1.revoke('k1b', T0); // unknown-key revocation must persist too

  const v2 = newVerifier(dir, clock).load();
  assert.deepStrictEqual(v2.verify(env), { ok: false, reason: 'replay' });
  assert.strictEqual(v2.registry.get('k1b').revokedAt, T0);
});

test('a crash during persist leaves the previous complete snapshot intact', () => {
  const dir = tmpDir();
  const clock = { t: T0 };
  const { descriptor, privateKey } = makeKey('k1');
  const v = newVerifier(dir, clock).load().addKey(descriptor);

  const env = signEnvelope(envelope('k1', T0), privateKey);
  const realRename = fs.renameSync;
  let injected = false;
  fs.renameSync = (...args) => {
    if (!injected) {
      injected = true;
      throw new Error('simulated crash during rename');
    }
    return realRename(...args);
  };
  let result;
  try {
    result = v.verify(env);
  } finally {
    fs.renameSync = realRename;
  }
  assert.deepStrictEqual(result, {
    ok: false,
    reason: 'persist_failed',
    error: 'simulated crash during rename',
  });
  // in-memory entry was rolled back so it matches durable state
  assert.strictEqual(v.windowSize('k1'), 0);

  const reloaded = newVerifier(dir, clock).load();
  assert.strictEqual(reloaded.verify(env).ok, true);
});

test('tampering with the snapshot is detected (HMAC)', () => {
  const dir = tmpDir();
  const clock = { t: T0 };
  const { descriptor } = makeKey('k1');
  const v = newVerifier(dir, clock).load().addKey(descriptor);
  const stateFile = path.join(dir, 'state.bin');
  const raw = fs.readFileSync(stateFile);
  raw[raw.length - 1] ^= 0xff; // flip a payload byte
  fs.writeFileSync(stateFile, raw);

  const fresh = newVerifier(dir, clock);
  assert.throws(() => fresh.load(), /rollback\/tamper|integrity/i);
});

test('rollback of the snapshot below the anchor generation is rejected', () => {
  const dir = tmpDir();
  const clock = { t: T0 };
  const { descriptor, privateKey } = makeKey('k1');
  const v = newVerifier(dir, clock).load().addKey(descriptor);
  const env = signEnvelope(envelope('k1', T0), privateKey);
  assert.strictEqual(v.verify(env).ok, true);

  const stateFile = path.join(dir, 'state.bin');
  const prevFile = stateFile + '.prev';
  fs.copyFileSync(prevFile, stateFile); // roll main back one generation

  const fresh = newVerifier(dir, clock);
  assert.throws(() => fresh.load(), /rollback\/tamper/i);
});

test('sliding window prunes old entries so memory stays bounded', () => {
  const dir = tmpDir();
  const clock = { t: T0 };
  const { descriptor, privateKey } = makeKey('k1');
  const v = newVerifier(dir, clock).load().addKey(descriptor);

  const first = signEnvelope(envelope('k1', T0), privateKey);
  assert.strictEqual(v.verify(first).ok, true);
  assert.strictEqual(v.windowSize('k1'), 1);

  // Jump past the window: the next accepted message evicts the old entry.
  clock.t = T0 + 400_000;
  const second = signEnvelope(envelope('k1', clock.t), privateKey);
  assert.strictEqual(v.verify(second).ok, true);
  assert.strictEqual(v.windowSize('k1'), 1);
});

test('asynchronous multi-region rotation with retransmission', () => {
  const dir = tmpDir();
  const clock = { t: T0 };
  const keys = ['r1', 'r2', 'r3'].map((r) => makeKey('key-' + r, { region: r }));
  const v = newVerifier(dir, clock).load();
  for (const k of keys) v.addKey(k.descriptor);

  // Interleave regions and retransmit each message once (a retransmit is a replay).
  const sent = [];
  for (let i = 0; i < 25; i++) {
    const k = keys[i % keys.length];
    const env = signEnvelope(envelope(k.descriptor.keyId, T0 + i, { i }), k.privateKey);
    sent.push(env);
  }
  // deliver out of order
  for (const env of [...sent].reverse()) assert.strictEqual(v.verify(env).ok, true);
  // retransmissions are rejected
  for (const env of sent) assert.deepStrictEqual(v.verify(env), { ok: false, reason: 'replay' });
});

test('persisted state is compact', () => {
  const dir = tmpDir();
  const clock = { t: T0 };
  const { descriptor, privateKey } = makeKey('k1');
  const v = newVerifier(dir, clock).load().addKey(descriptor);
  for (let i = 0; i < 200; i++) {
    const env = signEnvelope(envelope('k1', T0 + i, { i }), privateKey);
    assert.strictEqual(v.verify(env).ok, true);
  }
  const size = fs.statSync(path.join(dir, 'state.bin')).size;
  // ~200 fingerprints at 16 bytes + overhead; must be far below a JSON dump.
  assert.ok(size < 200 * 32, `state too large: ${size} bytes`);
});

test('missing snapshot starts clean but a lone valid anchor still guards', () => {
  const dir = tmpDir();
  const clock = { t: T0 };
  const { descriptor } = makeKey('k1');
  const v = newVerifier(dir, clock).load().addKey(descriptor);
  // delete state + prev but leave the anchor
  fs.rmSync(path.join(dir, 'state.bin'));
  fs.rmSync(path.join(dir, 'state.bin.prev'), { force: true });
  const fresh = newVerifier(dir, clock);
  assert.throws(() => fresh.load(), /rollback\/tamper/i);
});
